effect.shader:

 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

      #define O(x,a,b) smoothstep(0., 1., cos(x*6.2832)*.5+.5)*(a-b)+b  // oscillate between a & b
      #define A(v) mat2(cos((v*3.1416) + vec4(0, -1.5708, 1.5708, 0)))  // rotate
      #define s(p1, p2) c += .02/abs(L( u, K(p1, v, h), K(p2, v, h) )+.01)*k;  // segment

      // line
      float L(vec2 p, vec3 A, vec3 B)
      {
          vec2 a = A.xy, 
               b = B.xy - a;
               p -= a;
          float h = clamp(dot(p, b) / dot(b, b), 0., 1.);
          return length(p - b*h) + .01*mix(A.z, B.z, h);
      }

      // cam
      vec3 K(vec3 p, mat2 v, mat2 h)
      {
          p.zy *= v; // pitch
          p.zx *= h; // yaw
          // if (texelFetch(iChannel0, ivec2(80, 2), 0).x < 1.) // P key
              // p *= 6. / (p.z+6.); // perspective view
          return p;
      }

/////////////////////////
 void main ()
 {

     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

     vec2 umefx;
     // umefx = acScreenNorm; 
     umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     umefx.y*=acLayerSize.y/acLayerSize.x;

     umefx /= scale;
     umefx *= rot2m((0.0+angle)*0.0174533);
     umefx += vec2((0.0+position.x), (0.0-position.y))*vec2(-1.,1.)/500.;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     umefx /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

          vec2 R = iResolution.xy,
               u = umefx,
               m = (iMouse.xy*2.-R)/R.y;

          float t = iTime/60.0,
                o = t*6.0,
                j = (u.x > 0.) ? 1.0 : -1.0; // screen side

          // if (iMouse.z < 1.) // not clicking
          if(exl) {
              m = vec2(sin(t*6.2832)*2., sin(t*6.2832*2.)); // fig-8 movement 
          }

          mat2 v = A(m.y), // pitch
               h = A(m.x); // yaw

          vec3 c = vec3(0), p, 
               k = vec3(color2.r*5.0, color2.g*5.0, color2.b*5.0)/40. + xxa;

          // u.x -= j + j*.7; // split screen

          if (TYP == 0)
          {
              // k = k.brg; // shift color
              //p = vec3(1, .618, .382);  // stellated icosahedron
              //p = vec3(.382, -.618, 1); // dodecahedron

              // stella icosa to dodeca
              p = vec3(
                  O(o,   1.,  .382), 
                  O(o, .618, -.618), 
                  O(o, .382,    1.));
              s( vec3(-p.z,  p.x,    0), vec3(-p.z, -p.x,    0) )
              s( vec3(-p.z,  p.x,    0), vec3( p.y, -p.y, -p.y) )
              s( vec3(-p.z,  p.x,    0), vec3( p.y, -p.y,  p.y) )
              s( vec3(-p.z, -p.x,    0), vec3( p.y,  p.y, -p.y) )
              s( vec3(-p.z, -p.x,    0), vec3( p.y,  p.y,  p.y) )
              s( vec3( p.z,  p.x,    0), vec3( p.z, -p.x,    0) )
              s( vec3( p.z,  p.x,    0), vec3(-p.y, -p.y,  p.y) )
              s( vec3( p.z,  p.x,    0), vec3(-p.y, -p.y, -p.y) )
              s( vec3( p.z, -p.x,    0), vec3(-p.y,  p.y,  p.y) )
              s( vec3( p.z, -p.x,    0), vec3(-p.y,  p.y, -p.y) )
              s( vec3( p.x,    0, -p.z), vec3(-p.x,    0, -p.z) )
              s( vec3( p.x,    0, -p.z), vec3(-p.y,  p.y,  p.y) )
              s( vec3( p.x,    0, -p.z), vec3(-p.y, -p.y,  p.y) )
              s( vec3(-p.x,    0, -p.z), vec3( p.y, -p.y,  p.y) )
              s( vec3(-p.x,    0, -p.z), vec3( p.y,  p.y,  p.y) )
              s( vec3( p.x,    0,  p.z), vec3(-p.x,    0,  p.z) )
              s( vec3( p.x,    0,  p.z), vec3(-p.y,  p.y, -p.y) )
              s( vec3( p.x,    0,  p.z), vec3(-p.y, -p.y, -p.y) )
              s( vec3(-p.x,    0,  p.z), vec3( p.y,  p.y, -p.y) )
              s( vec3(-p.x,    0,  p.z), vec3( p.y, -p.y, -p.y) )
              s( vec3(   0,  p.z,  p.x), vec3(   0,  p.z, -p.x) )
              s( vec3(   0,  p.z,  p.x), vec3( p.y, -p.y, -p.y) )
              s( vec3(   0,  p.z,  p.x), vec3(-p.y, -p.y, -p.y) )
              s( vec3(   0,  p.z, -p.x), vec3( p.y, -p.y,  p.y) )
              s( vec3(   0,  p.z, -p.x), vec3(-p.y, -p.y,  p.y) )
              s( vec3(   0, -p.z,  p.x), vec3(   0, -p.z, -p.x) )
              s( vec3(   0, -p.z,  p.x), vec3( p.y,  p.y, -p.y) )
              s( vec3(   0, -p.z,  p.x), vec3(-p.y,  p.y, -p.y) )
              s( vec3(   0, -p.z, -p.x), vec3(-p.y,  p.y,  p.y) )
              s( vec3(   0, -p.z, -p.x), vec3( p.y,  p.y,  p.y) )
          }
          else if (TYP == 1)
          {
              //p = vec3(0, .618, 1);  // stellated dodecahedron
              //p = vec3(0, 1, -.618); // icosahedron

              // stella dodeca to icosa
              p = vec3(0, O(o, .618, 1.), O(o, 1., -.618));
              s( vec3(-p.y,  p.z,    0), vec3(   0, -p.y, -p.z) )
              s( vec3(-p.y,  p.z,    0), vec3(   0, -p.y,  p.z) )
              s( vec3(-p.y,  p.z,    0), vec3( p.z,    0, -p.y) )
              s( vec3(-p.y,  p.z,    0), vec3( p.z,    0,  p.y) )
              s( vec3( p.y,  p.z,    0), vec3( p.y, -p.z,    0) )
              s( vec3( p.y,  p.z,    0), vec3(   0, -p.y, -p.z) )
              s( vec3( p.y,  p.z,    0), vec3(   0, -p.y,  p.z) )
              s( vec3( p.y,  p.z,    0), vec3(-p.z,    0, -p.y) )
              s( vec3( p.y,  p.z,    0), vec3(-p.z,    0,  p.y) )
              s( vec3(-p.y, -p.z,    0), vec3(-p.y,  p.z,    0) )
              s( vec3(-p.y, -p.z,    0), vec3(   0,  p.y, -p.z) )
              s( vec3(-p.y, -p.z,    0), vec3(   0,  p.y,  p.z) )
              s( vec3(-p.y, -p.z,    0), vec3( p.z,    0, -p.y) )
              s( vec3(-p.y, -p.z,    0), vec3( p.z,    0,  p.y) )
              s( vec3( p.y, -p.z,    0), vec3(   0,  p.y, -p.z) )
              s( vec3( p.y, -p.z,    0), vec3(   0,  p.y,  p.z) )
              s( vec3( p.y, -p.z,    0), vec3(-p.z,    0, -p.y) )
              s( vec3( p.y, -p.z,    0), vec3(-p.z,    0,  p.y) )
              s( vec3(   0,  p.y, -p.z), vec3(   0,  p.y,  p.z) )
              s( vec3(   0,  p.y, -p.z), vec3( p.z,    0,  p.y) )
              s( vec3(   0,  p.y, -p.z), vec3(-p.z,    0,  p.y) )
              s( vec3(   0, -p.y, -p.z), vec3(   0, -p.y,  p.z) )
              s( vec3(   0, -p.y, -p.z), vec3( p.z,    0,  p.y) )
              s( vec3(   0, -p.y, -p.z), vec3(-p.z,    0,  p.y) )
              s( vec3(-p.z,    0, -p.y), vec3( p.z,    0, -p.y) )
              s( vec3(-p.z,    0,  p.y), vec3( p.z,    0,  p.y) )
              s( vec3(-p.z,    0, -p.y), vec3(   0,  p.y,  p.z) )
              s( vec3(-p.z,    0, -p.y), vec3(   0, -p.y,  p.z) )
              s( vec3( p.z,    0, -p.y), vec3(   0,  p.y,  p.z) )
              s( vec3( p.z,    0, -p.y), vec3(   0, -p.y,  p.z) )
          }

          fragColor = newLayer(color1, vec4(c + c*c, 0.0) );

 	    vec4 factor = mix(texColorX,fragColor,1.0);
 	    // vec4 factor;
 	     // = mix(texColorX,fragColor,1.0);
 	   // const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
         // float luminance = dot(fragColor.rgb, luminanceWeighting);
         // vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    // if(GRADMAP) { 
 	    // factor = mix(texColorX,gradmap,1.0);
 	     // }

 	    // vec4 xbuffer = texture2DCv(buff1.texture, acScreenNorm.st);

     vec4 resultfinal;
       if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
           // resultfinal = max(factor, texColor) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
 	// }
 }
